'use strict';
let contentReadOnly=false;let noteBoard='',noteLayout='columns',noteZoom=1,noteDrag=null;
const CARD_TYPES={note:'Ghi chú',heading:'Tiêu đề',link:'Liên kết',todo:'Checklist',board:'Bảng con',image:'Hình ảnh',video:'Video',audio:'Âm thanh',document:'Tài liệu',color:'Bảng màu',table:'Bảng dữ liệu',comment:'Nhận xét',line:'Đường nối',sketch:'Phác thảo',map:'Bản đồ'};
const safeId=v=>esc(v),fileURL=id=>'/api/assets/'+encodeURIComponent(id)+'?preview=1';
function boardChildren(id){const ids=new Set([id]);let changed=true;while(changed){changed=false;for(const n of data.notes||[])if(ids.has(n.boardId||'')&&!ids.has(n.id)){ids.add(n.id);changed=true;}}return ids;}
function noteContent(n){const content='<p>'+esc(n.text).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')+'</p>';let media='';if(n.fileId){const src=fileURL(n.fileId);if(n.type==='image')media=`<img class="board-media" src="${src}" alt="${esc(n.title)}" loading="lazy">`;else if(n.type==='audio')media=`<audio class="board-media" controls preload="none" src="${src}"></audio>`;else if(n.type==='video')media=`<video class="board-media" controls preload="metadata" src="${src}"></video>`;else media=`<a href="/api/assets/${encodeURIComponent(n.fileId)}">Tải tài liệu ↗</a>`;}
if(n.type==='todo')return (n.items||[]).map((item,i)=>`<label class="check-row"><input type="checkbox" data-note-check="${safeId(n.id)}" data-item="${i}" ${item.done?'checked':''}><span>${esc(item.text)}</span></label>`).join('');
if(n.type==='table')return '<div class="table-wrap"><table class="content-table">'+n.text.split('\n').map(row=>'<tr>'+row.split('|').map(cell=>'<td>'+esc(cell.trim())+'</td>').join('')+'</tr>').join('')+'</table></div>';
if(n.type==='color')return `<div class="color-swatch" style="background:${n.color}">${n.color}</div>`+content;
const gallery=(n.images||[]).filter(id=>/^[a-zA-Z0-9_-]{1,100}$/.test(id)).slice(0,20).map(id=>'<img loading="lazy" src="'+fileURL(id)+'" alt="Ảnh trong ghi chú">').join('');return media+(gallery?'<div class="note-inline-images">'+gallery+'</div>':'')+(n.sketch?`<img class="board-media" alt="Phác thảo" src="${n.sketch}">`:'')+content+(n.url?`<a href="${esc(n.url)}" rel="noopener noreferrer" target="_blank">${n.type==='map'?'Mở bản đồ':'Mở liên kết'} ↗</a>`:'');}
function contentCard(n,i){return `<article class="content-card ${n.type==='heading'?'heading-card':''}" data-card="${safeId(n.id)}" style="--card-color:${n.color};${noteLayout==='canvas'?`left:${n.x??(i%4)*310+24}px;top:${n.y??Math.floor(i/4)*300+24}px;width:${n.width||280}px;`:''}"><div class="card-handle" draggable="true" data-note-drag="${safeId(n.id)}" tabindex="0" aria-label="Di chuyển ${esc(n.title)}"><span>${esc(CARD_TYPES[n.type]||'Ghi chú')}</span><span>⠿</span></div>${n.type!=='board'?`<h3>${esc(n.title)}</h3>`:''}${noteContent(n)}<div class="content-actions"><button type="button" data-note-edit="${safeId(n.id)}">Sửa</button><button type="button" data-note-copy="${safeId(n.id)}">Nhân bản</button><button type="button" data-note-files="${safeId(n.id)}">Tệp</button><button type="button" data-note-delete="${safeId(n.id)}">Thùng rác</button></div></article>`;}
notesPage=function(){const notes=(data.notes||[]).filter(n=>(n.title+' '+n.text+' '+n.group).toLowerCase().includes(query.toLowerCase()));return heading('KHÔNG GIAN Ý TƯỞNG','Ghi chú','Ghi nhanh, giữ ý tưởng và đính kèm tài liệu.','<button class="btn primary" data-note-new>+ Ghi chú mới</button>')+`<div class="keep-grid">${notes.map(n=>`<article class="keep-card" style="--card-color:${n.color}"><small>${esc(n.group||'Ghi chú')}</small><h3>${esc(n.title)}</h3>${noteContent(n)}<div class="keep-actions"><button class="btn" data-note-edit="${safeId(n.id)}" aria-label="Sửa ghi chú ${esc(n.title)}">${svgIcon('edit')} Sửa</button><button class="btn" data-note-files="${safeId(n.id)}">${svgIcon('attach')} Tệp</button><button class="btn" data-note-delete="${safeId(n.id)}" aria-label="Xóa ghi chú ${esc(n.title)}">${svgIcon('trash')}</button></div></article>`).join('')||'<div class="empty">Chưa có ghi chú. Thêm một ý tưởng đầu tiên.</div>'}</div>`;};
function noteAssetIsImage(file){return file.mime?.startsWith('image/')||/\.(png|jpe?g|webp|gif|avif)$/i.test(file.name);}
function noteAssetKind(file){const ext=String(file.name||'').split('.').pop().toLowerCase();if(file.mime?.startsWith('audio/')||['mp3','wav','ogg','m4a','aac'].includes(ext))return 'AUDIO';if(file.mime?.startsWith('video/')||['mp4','webm','mov','m4v'].includes(ext))return 'VIDEO';return ({pdf:'PDF',doc:'DOC',docx:'DOCX',xls:'XLS',xlsx:'XLSX',ppt:'PPT',pptx:'PPTX',csv:'CSV',txt:'TXT',zip:'ZIP',rar:'RAR',md:'MD'})[ext]||'TỆP';}
noteForm=function(n){
 const id=n?.id||uid();let busy=false,formBase=n?structuredClone(n):null;
 modal(`<div class="note-composer"><input name="title" aria-label="Tiêu đề" placeholder="Tiêu đề" maxlength="150" value="${esc(n?.title||'')}"><textarea name="text" aria-label="Nội dung ghi chú" placeholder="Viết ghi chú…" maxlength="10000">${esc(n?.text||'')}</textarea><div class="note-links">${field('Liên kết','url',n?.url||'','url',false,2000)}</div><div id="inline-note-files"></div><p id="inline-note-status" role="status"></p><div class="note-toolbar"><label class="btn">${svgIcon('attach')}Tải tệp<input id="inline-note-upload" type="file" multiple hidden></label><label class="note-color" title="Màu thẻ"><span>Màu thẻ</span><input name="color" type="color" aria-label="Màu thẻ" value="${n?.color||'#7950c8'}"></label><label class="note-group">Nhãn ghi chú<input name="group" aria-label="Nhãn" placeholder="Ví dụ: Ý tưởng" maxlength="80" value="${esc(n?.group||'')}"></label><button class="btn primary" id="note-save" type="submit">${svgIcon('check')}Lưu</button></div><small>25 MB/tệp · Liên kết http/https</small></div>`,()=>{if(busy)return; if(commit()){ $('#editor').close();render();}},true);
 $('#editor').classList.add('keep-editor');$('#editor').addEventListener('close',()=>$('#editor').classList.remove('keep-editor'),{once:true});
 const commit=()=>{
  n=data.notes?.find(x=>x.id===id)||null;if(formBase&&!n){notify('Ghi chú đã bị xóa trên thiết bị khác. Nội dung đang nhập được giữ để bạn sao chép.');return false;}
  const form=$('#editor-form'),fd=new FormData(form),url=String(fd.get('url')||'').trim();if(url&&!/^https?:\/\//i.test(url)){notify('Liên kết cần bắt đầu bằng https:// hoặc http://');return false;}
  data.notes||=[];if(!n&&data.notes.length>=500){notify('Tối đa 500 ghi chú.');return false;}const extra=typeof noteExtraValues==='function'?noteExtraValues(form,n):{};if(extra===false)return false;
  const value={...extra,title:String(fd.get('title')||'').trim()||'Ghi chú',text:String(fd.get('text')||''),url,group:String(fd.get('group')||'').trim(),color:fd.get('color')};
  if(n){const previous=structuredClone(n);try{const candidate={...formBase,...value,id},merged=typeof mergeWorkspaceValue==='function'?mergeWorkspaceValue(formBase,candidate,n):candidate;Object.assign(n,merged);if(save()===false){Object.keys(n).forEach(k=>delete n[k]);Object.assign(n,previous);return false;}formBase=structuredClone(candidate);return true;}catch{notify('Ghi chú đang được sửa cùng lúc trên thiết bị khác. Hãy giữ nội dung đang nhập trước khi mở lại.');return false;}}
  n={id,type:'note',...value};data.notes.push(n);if(save()===false){data.notes=data.notes.filter(x=>x.id!==id);n=null;return false;}formBase=structuredClone(n);return true;
 };
 $('#editor').noteCommit=commit;$('#editor').dataset.noteId=id;
 const refresh=async()=>{const r=await requestAPI('assets?scope='+encodeURIComponent('note:'+id));const el=$('#inline-note-files');if(!el)return;const files=r.files||[],images=files.filter(noteAssetIsImage),documents=files.filter(f=>!noteAssetIsImage(f));const imageCards=images.map(f=>`<figure class="note-attachment-image"><div class="note-attachment-image-preview"><img src="/api/assets/${encodeURIComponent(f.id)}?preview=1" loading="lazy" alt="${esc(f.name)}"></div><figcaption><span title="${esc(f.name)}">${esc(f.name)}</span><button type="button" class="note-attachment-remove" data-note-asset-remove="${esc(f.id)}" aria-label="Gỡ ảnh ${esc(f.name)} khỏi ghi chú" title="Gỡ khỏi ghi chú">×</button></figcaption></figure>`).join('');const fileRows=documents.map(f=>`<div class="note-attachment-file"><span class="note-attachment-kind" data-kind="${noteAssetKind(f)}">${noteAssetKind(f)}</span><div class="note-attachment-meta"><a href="/api/assets/${encodeURIComponent(f.id)}" title="${esc(f.name)}">${esc(f.name)}</a><small>${formatSize(f.size)}</small></div><button type="button" class="note-attachment-remove" data-note-asset-remove="${esc(f.id)}" aria-label="Gỡ ${esc(f.name)} khỏi ghi chú" title="Gỡ khỏi ghi chú">×</button></div>`).join('');el.innerHTML=(images.length?`<section class="note-attachment-group"><h4>Hình ảnh <span>${images.length}</span></h4><div class="note-attachment-image-grid">${imageCards}</div></section>`:'')+(documents.length?`<section class="note-attachment-group"><h4>Tài liệu & tệp <span>${documents.length}</span></h4><div class="note-attachment-file-list">${fileRows}</div></section>`:'');};
 if(n)refresh().catch(e=>{$('#inline-note-status').textContent=e.message;});
 $('#inline-note-files').addEventListener('click',async e=>{const button=e.target.closest('[data-note-asset-remove]');if(!button)return;const assetId=button.dataset.noteAssetRemove;if(!/^[a-zA-Z0-9_-]{1,100}$/.test(assetId))return;button.disabled=true;const oldImages=n?.images? [...n.images]:null,oldFileId=n?.fileId;try{if(n?.images)n.images=n.images.filter(x=>x!==assetId);if(n?.fileId===assetId)delete n.fileId;if(!save()){if(n){if(oldImages)n.images=oldImages;else delete n.images;if(oldFileId)n.fileId=oldFileId;else delete n.fileId;}throw Error('Không lưu được thay đổi trên thiết bị.');}await requestAPI('assets/'+encodeURIComponent(assetId)+'/trash','POST',{});const current=data.notes?.find(x=>x.id===id);if(current){if(current.images){current.images=current.images.filter(x=>x!==assetId);if(!current.images.length)delete current.images;}if(current.fileId===assetId)delete current.fileId;save();}await refresh();render();$('#inline-note-status').textContent='Đã gỡ tệp khỏi ghi chú · có thể khôi phục trong Thùng rác.';}catch(error){if(n){if(oldImages)n.images=oldImages;else delete n.images;if(oldFileId)n.fileId=oldFileId;else delete n.fileId;save();}button.disabled=false;$('#inline-note-status').textContent=error.message;}});
 $('#inline-note-upload').onchange=async e=>{const files=Array.from(e.target.files);if(!files.length||!commit())return;busy=true;e.target.disabled=true;$('#note-save').disabled=true;const status=$('#inline-note-status');try{await flushCloud();if(dirty)throw Error('Ghi chú chưa đồng bộ. Vui lòng thử lại.');for(const file of files){if(!file.size||file.size>25000000)throw Error('Tệp rỗng hoặc vượt 25 MB.');let upload;try{upload=await requestAPI('assets/start','POST',{name:file.name,size:file.size,mime:file.type,scope:'note:'+id});let part=0;for(let offset=0;offset<file.size;offset+=upload.chunk){const response=await fetch('/api/assets/'+upload.id+'/part?n='+(++part),{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream'},body:file.slice(offset,offset+upload.chunk)});if(!response.ok)throw Error((await response.json()).error||'Tải thất bại');status.textContent=file.name+' · '+Math.round(Math.min(offset+upload.chunk,file.size)/file.size*100)+'%';}await requestAPI('assets/'+upload.id+'/complete','POST',{});if(file.type.startsWith('image/')){n.images||=[];if(n.images.length<20&&!n.images.includes(upload.id))n.images.push(upload.id);}else n.fileId||=upload.id;save();}catch(err){if(upload)await requestAPI('assets/'+upload.id+'/abort','POST',{}).catch(()=>{});throw err;}}await refresh();status.textContent='Đã tải xong. Ghi chú được lưu trước khi tải tệp.';render();}catch(err){status.textContent=err.message;}finally{busy=false;e.target.disabled=false;e.target.value='';const b=$('#note-save');if(b)b.disabled=false;}};
};
function moveToTrash(before){data.trash||=structuredClone(before.trash||[]);const put=(kind,value,parent)=>data.trash.push({id:uid(),at:Date.now(),kind,name:value.title||value.name||value.text||'Dữ liệu',payload:JSON.stringify(value),parent:parent?JSON.stringify(parent):''});for(const p of before.projects){const next=data.projects.find(x=>x.id===p.id);if(!next){put('project',p);continue;}for(const t of p.tasks){const nt=next.tasks.find(x=>x.id===t.id);if(!nt){put('task',t,{...p,tasks:[]});continue;}for(const c of t.checks)if(!nt.checks.some(x=>x.id===c.id))put('check',c,{project:{...p,tasks:[]},task:{...t,checks:[]}});}}for(const n of before.notes||[])if(!(data.notes||[]).some(x=>x.id===n.id))put('note',n);}
const oldConfirmDelete=confirmDelete;confirmDelete=function(kind,fn){oldConfirmDelete(kind,()=>{const before=structuredClone(data);fn();moveToTrash(before);});$('#editor-body .help-copy').textContent='Dữ liệu chuyển vào Thùng rác, có thể khôi phục trong 30 ngày. Sau đó hệ thống tự dọn.';};
function trashPage(){return heading('KHÔI PHỤC DỮ LIỆU','Thùng rác','Giữ 30 ngày kể từ lúc xóa. Tệp và ghi chú chỉ bị dọn sau thời hạn này.')+`<section class="panel">${(data.trash||[]).map(x=>`<div class="trash-row"><div><strong>${esc(x.name)}</strong><small>${new Date(x.at).toLocaleString('vi-VN')} · ${Math.max(0,30-Math.floor((Date.now()-x.at)/86400000))} ngày còn lại</small></div><button class="btn" data-restore-item="${safeId(x.id)}">Khôi phục</button></div>`).join('')||'<p>Không có dữ liệu đã xóa.</p>'}</section><section class="panel"><h3>Tệp trong Thùng rác</h3><div id="file-trash-list">Đang tải…</div></section>`;}
async function loadTrashFiles(){try{const r=await requestAPI('assets/trash');if(!$('#file-trash-list'))return;$('#file-trash-list').innerHTML=[...r.files.map(f=>({...f,legacy:false})),...r.legacy.map(f=>({...f,legacy:true}))].map(f=>`<div class="trash-row"><span>${esc(f.name)} · ${formatSize(f.size)}</span><button class="btn" data-restore-file="${f.id}" data-legacy="${f.legacy}">Khôi phục</button></div>`).join('')||'Không có tệp đã xóa.';}catch(e){if($('#file-trash-list'))$('#file-trash-list').textContent=e.message;}}
function restoreItem(id){const record=data.trash?.find(x=>x.id===id);if(!record)return;const next=structuredClone(data),value=JSON.parse(record.payload),parent=record.parent?JSON.parse(record.parent):null;let target;if(record.kind==='project'){if(next.projects.some(x=>x.id===value.id))return notify('Dự án đã tồn tại.');next.projects.push(value);}if(record.kind==='note'){next.notes||=[];if(next.notes.some(x=>x.id===value.id))return notify('Ghi chú đã tồn tại.');if(value.boardId&&!next.notes.some(x=>x.id===value.boardId))value.boardId='';next.notes.push(value);if(value.type==='board'){const ids=new Set([value.id]);let changed=true;while(changed){changed=false;for(const r of next.trash){if(r.kind!=='note'||ids.has(JSON.parse(r.payload).id))continue;const child=JSON.parse(r.payload);if(ids.has(child.boardId)&&!next.notes.some(n=>n.id===child.id)){next.notes.push(child);ids.add(child.id);changed=true;}}}next.trash=next.trash.filter(r=>r.kind!=='note'||!ids.has(JSON.parse(r.payload).id));}}if(record.kind==='task'){target=next.projects.find(x=>x.id===parent.id);if(!target){target=parent;next.projects.push(target);}if(target.tasks.some(x=>x.id===value.id))return notify('Task đã tồn tại.');target.tasks.push(value);}if(record.kind==='check'){target=next.projects.find(x=>x.id===parent.project.id);if(!target){target=parent.project;next.projects.push(target);}let task=target.tasks.find(x=>x.id===parent.task.id);if(!task){task=parent.task;target.tasks.push(task);}if(!task.checks.some(x=>x.id===value.id))task.checks.push(value);syncChecks(task);}next.trash=next.trash.filter(x=>x.id!==id);if(!valid(next))return notify('Không thể khôi phục: dữ liệu vượt giới hạn hoặc không tương thích.');data=next;save();render();notify('Đã khôi phục.');}
function formatSize(n){return n>=1073741824?(n/1073741824).toFixed(2)+' GiB':n>=1048576?(n/1048576).toFixed(1)+' MiB':Math.ceil(n/1024)+' KiB';}
async function assetPanel(scope,legacy){if(dirty){await flushCloud();if(dirty)return notify('Cần đồng bộ trước khi tải tệp.');}modal('<h2>Kho tệp riêng tư</h2><p>Tối đa 25 MB/tệp · kho Kanban 1 GB, gồm Thùng rác và tệp đang tải. Tệp lớn: thêm liên kết trong thẻ.</p><input id="large-file" type="file" multiple aria-label="Chọn tệp"><progress id="upload-progress" value="0" max="100"></progress><p id="upload-status" role="status"></p><button class="btn" type="button" id="cancel-upload" hidden>Hủy tải</button><p id="storage-usage" role="status"></p><div id="asset-list"></div>',null,true);let cancelled=false,busy=false;const refresh=async()=>{const r=await requestAPI('assets?scope='+encodeURIComponent(scope));let files=r.files;if($('#storage-usage'))$('#storage-usage').textContent='Kho Kanban: '+formatSize(r.used)+' / '+formatSize(r.quota)+' (gồm Thùng rác và tệp đang tải)';if(legacy){const l=await requestAPI('files?project='+encodeURIComponent(legacy.p)+'&task='+encodeURIComponent(legacy.t||''));files=[...files,...l.files.map(f=>({...f,legacy:true}))];}if(!$('#asset-list'))return;$('#asset-list').innerHTML=files.map(f=>`<div class="trash-row"><a href="/api/${f.legacy?'files':'assets'}/${f.id}">${esc(f.name)}</a><small>${formatSize(f.size)}</small><button class="btn" type="button" data-trash-file="${f.id}" data-legacy="${!!f.legacy}">Thùng rác</button>${scope.startsWith('note:')&&!f.legacy?`<button class="btn" type="button" data-use-file="${f.id}" data-note-id="${safeId(scope.slice(5))}">Dùng trong thẻ</button>`:''}</div>`).join('')||'<p>Chưa có tệp.</p>';};await refresh();$('#cancel-upload').onclick=()=>cancelled=true;$('#large-file').onchange=async e=>{if(busy)return;busy=true;cancelled=false;e.target.disabled=true;$('#cancel-upload').hidden=false;try{for(const file of e.target.files){if(cancelled)break;if(!file.size||file.size>25000000)throw Error('Tệp rỗng hoặc vượt 25 MB.');let id;try{const start=await requestAPI('assets/start','POST',{name:file.name,size:file.size,mime:file.type,scope});id=start.id;let part=0;for(let offset=0;offset<file.size;offset+=start.chunk){if(cancelled)throw Error('Đã hủy tải.');const chunk=file.slice(offset,offset+start.chunk);let ok=false;part++;for(let attempt=0;attempt<3;attempt++){try{const response=await fetch('/api/assets/'+id+'/part?n='+part,{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream'},body:chunk});if(!response.ok)throw Error((await response.json()).error||'Tải thất bại.');ok=true;break;}catch(err){if(attempt===2)throw err;}}if(ok&&$('#upload-status')){$('#upload-progress').value=Math.round(Math.min(offset+chunk.size,file.size)/file.size*100);$('#upload-status').textContent=file.name+' · '+$('#upload-progress').value+'%';}}await requestAPI('assets/'+id+'/complete','POST',{});await refresh();}catch(err){if(id)await requestAPI('assets/'+id+'/abort','POST',{}).catch(()=>{});throw err;}}if($('#upload-status'))$('#upload-status').textContent=cancelled?'Đã hủy.':'Đã tải xong.';}catch(err){if($('#upload-status'))$('#upload-status').textContent=err.message;}finally{busy=false;if($('#large-file'))$('#large-file').disabled=false;if($('#cancel-upload'))$('#cancel-upload').hidden=true;}};$('#asset-list').onclick=async e=>{const el=e.target.closest('[data-trash-file],[data-use-file]');if(!el)return;try{if(el.dataset.trashFile){await requestAPI((el.dataset.legacy==='true'?'legacy-files/':'assets/')+el.dataset.trashFile+'/trash','POST',{});await refresh();}else{const n=data.notes.find(x=>x.id===el.dataset.noteId);n.fileId=el.dataset.useFile;save();$('#editor').close();render();}}catch(err){notify(err.message);}};}
filePanel=(p,t)=>assetPanel('project:'+p.id+(t?':task:'+t.id:''),{p:p.id,t:t?.id});
const trashNav=document.createElement('button');trashNav.className='nav';trashNav.dataset.view='trash';trashNav.innerHTML='<span>'+svgIcon('trash')+'</span>Thùng rác';document.querySelector('.sidebar nav').append(trashNav);
const beforeContentRender=render;render=function(){beforeContentRender();if(view==='trash'){$('#main').innerHTML=trashPage();loadTrashFiles();}if(contentReadOnly){document.querySelectorAll('.content-card input').forEach(el=>el.disabled=true);document.querySelectorAll('.content-toolbar,.content-actions').forEach(el=>el.hidden=true);$('#main').insertAdjacentHTML('afterbegin','<p class="share-notice">Bản chia sẻ chỉ xem · Tệp riêng tư không được chia sẻ.</p>');}if(view==='notes'){$('#crumb').textContent='Ghi chú';$('#search').placeholder='Tìm trong bảng…';}else $('#search').placeholder='Tìm công việc…';};
document.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement)||!img.closest('.note-inline-images,.content-card .board-media'))return;const gallery=img.closest('.note-inline-images');img.remove();if(gallery&&!gallery.querySelector('img'))gallery.remove();},true);
$('#search').addEventListener('input',e=>{if(noteSearchActive){view='notes';query=e.target.value;render();}},true);let noteSearchActive=false;document.addEventListener('focusin',e=>{if(e.target.id==='search')noteSearchActive=view==='notes';});
document.addEventListener('change',e=>{if(e.target.id==='note-layout'){noteLayout=e.target.value;render();}if(e.target.dataset.noteCheck){const n=data.notes.find(x=>x.id===e.target.dataset.noteCheck);if(contentReadOnly)return;const item=n?.items?.[Number(e.target.dataset.item)];if(!item)return;item.done=e.target.checked;save();render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-note-files],[data-restore-item],[data-restore-file]');if(!b)return;try{if(b.dataset.noteFiles)await assetPanel('note:'+b.dataset.noteFiles);if(b.dataset.restoreItem)restoreItem(b.dataset.restoreItem);if(b.dataset.restoreFile){await requestAPI((b.dataset.legacy==='true'?'legacy-files/':'assets/')+b.dataset.restoreFile+'/restore','POST',{});await loadTrashFiles();}}catch(err){notify(err.message);}});

render();

document.addEventListener('click',async e=>{if(!e.target.closest('[data-board-share]'))return;modal('<h2>Chia sẻ bảng nội dung</h2><p>Tạo bản chụp chỉ xem, có hiệu lực 7 ngày. Người có liên kết xem được nội dung và bản phác thảo; tệp đính kèm vẫn riêng tư. Thay đổi sau khi tạo không cập nhật bản chia sẻ.</p><button type="button" class="btn primary" id="create-share">Tạo liên kết chỉ xem</button><button type="button" class="btn" id="revoke-share">Thu hồi tất cả liên kết của tôi</button><p id="share-status" role="status"></p>',null,true);$('#create-share').onclick=async()=>{try{await flushCloud();if(dirty)throw Error('Hãy đợi đồng bộ xong.');const r=await requestAPI('board-share','POST',{boardId:noteBoard});$('#share-status').innerHTML='<a href="'+esc(r.url)+'">'+esc(r.url)+'</a>';}catch(error){$('#share-status').textContent=error.message;}};$('#revoke-share').onclick=async()=>{try{await requestAPI('board-share','POST',{revoke:true});$('#share-status').textContent='Đã thu hồi các liên kết.';}catch(error){$('#share-status').textContent=error.message;}};});
document.addEventListener('click',e=>{if(!contentReadOnly)return;const target=e.target.closest('button,input,select');if(target&&!target.matches('[data-open-board],[data-zoom],#note-layout,[data-board-export],[data-board-print]')){e.preventDefault();e.stopImmediatePropagation();}},true);document.addEventListener('pointerdown',e=>{if(contentReadOnly&&e.target.closest('[data-note-drag]'))e.stopImmediatePropagation();},true);document.addEventListener('dragstart',e=>{if(contentReadOnly){e.preventDefault();e.stopImmediatePropagation();}},true);
